using System;
using System.Linq;
class MonitorTests {
 static int checks,failures;static void Check(string n,bool ok){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(!ok)failures++;}
 static SystemSample Sample(DateTime now,double? cpu){return new SystemSample{Utc=now,Cpu=cpu,MemoryTotal=16,MemoryUsed=4,NetworkId="a",Download=1024,Upload=512};}
 static int Main(){var cfg=new MonitorConfig();foreach(var r in cfg.Rules)r.Enabled=r.Key=="cpu";var engine=new MonitorEngine(cfg);var now=new DateTime(2026,10,21,10,0,0,DateTimeKind.Utc);Check("first high sample never immediately alerts",engine.Observe(Sample(now,95)).Length==0);Check("brief spike does not alert",engine.Observe(Sample(now.AddSeconds(3),95)).Length==0);engine.Observe(Sample(now.AddSeconds(6),20));Check("recovery cancels spike",engine.Observe(Sample(now.AddSeconds(9),95)).Length==0);engine.Observe(Sample(now.AddSeconds(12),95));engine.Observe(Sample(now.AddSeconds(15),95));var alerts=engine.Observe(Sample(now.AddSeconds(18),95));Check("sustained high emits exact metric and threshold",alerts.Length==1&&alerts[0].Key=="cpu"&&alerts[0].Value==95&&alerts[0].Threshold==90);Check("ongoing overload does not repeat",engine.Observe(Sample(now.AddSeconds(21),96)).Length==0);
 engine.Observe(Sample(now.AddSeconds(24),85));Check("hysteresis prevents jitter rearm",engine.Observe(Sample(now.AddSeconds(27),96)).Length==0);engine.Observe(Sample(now.AddSeconds(30),30));for(int i=33;i<=45;i+=3)Check("cooldown suppresses rapid rearm "+i,engine.Observe(Sample(now.AddSeconds(i),95)).Length==0);engine.Observe(Sample(now.AddSeconds(150),95));engine.Observe(Sample(now.AddSeconds(153),95));engine.Observe(Sample(now.AddSeconds(156),95));Check("gap resets continuous duration",engine.Observe(Sample(now.AddSeconds(159),95)).Length==1);
 var missing=new MonitorEngine(new MonitorConfig());Check("unknown sensor never alerts",missing.Observe(new SystemSample{Utc=now}).Length==0);missing.Config.HoldSeconds=0;foreach(var r in missing.Config.Rules)r.Enabled=r.Key=="cpu";missing.Observe(Sample(now.AddSeconds(3),99));missing.Observe(Sample(now.AddSeconds(6),null));Check("missing sample clears alert streak",missing.Observe(Sample(now.AddSeconds(9),99)).Length==0);missing.Config.Alerts=false;Check("master switch suppresses alerts",missing.Observe(Sample(now.AddSeconds(12),100)).Length==0);
 var traffic=new MonitorEngine(new MonitorConfig());traffic.Observe(Sample(now,0));traffic.Observe(Sample(now.AddSeconds(3),0));Check("traffic integrates selected interface valid interval",traffic.Config.Days.Count==1&&traffic.Config.Days[0].Download==3072&&traffic.Config.Days[0].Upload==1536);traffic.Observe(Sample(now.AddHours(1),0));Check("sleep or exit gap not extrapolated",traffic.Config.Days[0].Download==3072);var changed=Sample(now.AddHours(1).AddSeconds(3),0);changed.NetworkId="b";traffic.Observe(changed);Check("interface change skips discontinuity",traffic.Config.Days[0].Download==3072);changed.Utc=changed.Utc.AddSeconds(3);traffic.Observe(changed);Check("new interface resumes counting",traffic.Config.Days[0].Download==6144);Check("unknown value displays dash",MonitorEngine.Format(new SystemSample(),"cpuTemp")=="—");Check("memory percent uses physical total",MonitorEngine.Value(Sample(now,0),"memory")==25);var policy=new VoicePolicy();policy.Mark("ambient",null,0,3);Check("alert audio bypasses ambient cooldown",policy.CanPlay("monitor-alert",null,1,1,false,false));policy.Mark("monitor-alert",null,1,1);Check("alert sounds have global cooldown",!policy.CanPlay("monitor-alert",null,2,1,false,false));Check("full-screen suppression still applies",!policy.CanPlay("monitor-alert",null,60,1,false,true));
 var invalid=new MonitorEngine(new MonitorConfig());invalid.Config.HoldSeconds=0;foreach(var r in invalid.Config.Rules){r.Enabled=true;r.Threshold=-1;}Check("invalid imported thresholds stay disabled",invalid.Observe(Sample(now,100)).Length==0);
 Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
}
